export function TestimonialsSection() {
  const featuredId =
    testimonials.find((testimonial) => testimonial.isHighlight)?.id ??
    testimonials[0].id;
  const [activeId, setActiveId] = useState<string | null>(featuredId);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const observerOptions = {
      root: null,
      // Target the center of the screen with a narrow horizontal band
      rootMargin: "-48% 0px -48% 0px",
      threshold: 0,
    };

    const handleIntersection = (entries: IntersectionObserverEntry[]) => {
      // Only apply this logic on mobile viewports
      if (window.innerWidth >= 768) return;

      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          const id = entry.target.getAttribute("data-testimonial-id");
          if (id) {
            setActiveId(id);
          }
        }
      });
    };

    const observer = new IntersectionObserver(handleIntersection, observerOptions);

    const cards = containerRef.current?.querySelectorAll("[data-testimonial-id]");
    cards?.forEach((card) => observer.observe(card));

    return () => observer.disconnect();
  }, []);

  const handleCardInteraction = (id: string) => {
    setActiveId(id);
  };

  return (
    <section className="relative flex min-h-screen w-full items-center overflow-hidden bg-black py-8 text-white md:py-10">
      <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_top,rgba(14,165,233,0.12),transparent_30%),radial-gradient(circle_at_bottom,rgba(244,63,94,0.08),transparent_28%)]" />

      <div className="container relative mx-auto px-4 md:px-6">
        {/* <div className="pointer-events-none absolute inset-y-0 left-4 hidden w-px bg-zinc-800 md:block md:left-6" />
        <div className="pointer-events-none absolute inset-y-0 right-4 hidden w-px bg-zinc-800 md:block md:right-6" /> */}

        {/* Header */}
        <div className="mx-auto mb-8 flex max-w-3xl flex-col items-center text-center md:mb-12">
          <motion.div
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            viewport={{ once: true }}
            transition={{ duration: 0.45, ease: "easeOut" }}
            className="mb-4 inline-flex items-center gap-2 px-4 py-2 text-[12px] font-medium uppercase tracking-[0.18em] text-cyan-400 font-sans"
          >
            <Boxes size={16} color="#d7545d" />
            Testimonials
          </motion.div>

          <motion.h2
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            viewport={{ once: true }}
            transition={{ delay: 0.12, duration: 0.55, ease: "easeOut" }}
            className="mb-4 max-w-2xl text-[34px] font-serif font-normal leading-[1.05] tracking-[-0.05em] md:mb-6 md:text-[56px]"
          >
            What Developers Are Saying
          </motion.h2>

          <motion.p
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            viewport={{ once: true }}
            transition={{ delay: 0.28, duration: 0.5, ease: "easeOut" }}
            className="max-w-xl px-2 text-[15px] font-normal leading-7 tracking-[-0.02em] text-zinc-400 md:px-4 md:text-[16px] md:leading-[26px] md:tracking-[-0.03em]"
          >
            Real experiences from developers who&apos;ve tried the tool in their
            everyday workflow from quick fixes to improving productivity.
          </motion.p>
        </div>

        {/* Cards Parent */}
        <motion.div
          ref={containerRef}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.1 }}
          className="relative mx-auto flex w-full max-w-7xl flex-col gap-3 border-t border-zinc-800 md:h-[460px] md:flex-row md:gap-0 md:overflow-hidden md:border md:border-zinc-900 md:bg-zinc-950/20 md:backdrop-blur-sm"
          variants={{
            hidden: { opacity: 0 },
            visible: {
              opacity: 1,
              transition: {
                delay: 0.45,
                duration: 0.35,
                ease: "easeOut",
                delayChildren: 0.18,
                staggerChildren: 0.08,
              },
            },
          }}
        >
          <div className="pointer-events-none absolute inset-x-0 top-0 z-20 hidden h-px bg-zinc-800 md:block" />
          {testimonials.map((testimonial) => (
            <TestimonialCard
              key={testimonial.id}
              {...testimonial}
              isExpanded={activeId === testimonial.id}
              onHover={() => handleCardInteraction(testimonial.id)}
              onClick={() => handleCardInteraction(testimonial.id)}
            />
          ))}
        </motion.div>
      </div>
    </section>
  );
}
